import { icon } from './icons.js';
export function loopSculpture(){return `<div class="loop-sculpture" data-motion-art role="img" aria-label="An unbroken Loop connects conversations, plans, meetings, and knowledge."><svg class="ribbon-art" viewBox="0 0 560 480" aria-hidden="true"><defs><linearGradient id="ribbonFront" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="var(--ribbon-a)"/><stop offset=".28" stop-color="var(--ribbon-b)"/><stop offset=".55" stop-color="var(--ribbon-c)"/><stop offset=".8" stop-color="var(--ribbon-a)"/><stop offset="1" stop-color="var(--ribbon-d)"/></linearGradient><linearGradient id="ribbonEdge" x1="0" y1="1" x2="1" y2="0"><stop stop-color="var(--ribbon-d)"/><stop offset=".45" stop-color="var(--ribbon-c)"/><stop offset="1" stop-color="var(--ribbon-a)"/></linearGradient></defs><g class="sculpture-grid"><ellipse cx="280" cy="268" rx="238" ry="154"/><ellipse cx="280" cy="268" rx="197" ry="124"/><path d="M40 268H520M280 100V430"/></g><path class="ribbon-shadow" d="M280 253C195 102 83 153 108 259C132 363 233 284 280 253C327 222 419 141 448 238C479 345 365 407 280 253Z"/><path class="ribbon-depth" d="M280 240C195 89 83 140 108 246C132 350 233 271 280 240C327 209 419 128 448 225C479 332 365 394 280 240Z"/><path class="ribbon-main" d="M280 225C195 74 83 125 108 231C132 335 233 256 280 225C327 194 419 113 448 210C479 317 365 379 280 225Z"/><path class="ribbon-highlight" d="M280 218C195 67 83 118 108 224C132 328 233 249 280 218C327 187 419 106 448 203C479 310 365 372 280 218Z"/><path class="ribbon-trace" pathLength="100" d="M280 225C195 74 83 125 108 231C132 335 233 256 280 225C327 194 419 113 448 210C479 317 365 379 280 225Z"/></svg><div class="sculpture-node node-chat">${icon('chat',18)}<span>A conversation</span><i></i></div><div class="sculpture-node node-task">${icon('check',18)}<span>A clear next step</span><i></i></div><div class="sculpture-node node-meeting">${icon('meetings',18)}<span>A shared decision</span><i></i></div><div class="sculpture-node node-knowledge">${icon('docs',18)}<span>Knowledge that stays</span><i></i></div><span class="sculpture-caption">A CONTINUOUS THREAD, FROM THOUGHT TO DONE.</span></div>`;}
export function connectedSequence(){return `<div class="connected-sequence reveal" data-sequence><div class="sequence-top"><span class="eyebrow">ONE THOUGHT. FOUR CONNECTED MOMENTS.</span><button class="btn text sequence-replay" type="button" aria-label="Replay connected workflow">${icon('play',14)}Replay</button></div><div class="sequence-track"><div class="sequence-line" aria-hidden="true"><i></i></div>${[['chat','Conversation','“Who can take the first pass?”'],['projects','Task','An owner and a next step.'],['meetings','Meeting','A decision, with the context.'],['docs','Knowledge','What we learned, kept close.']].map(([i,title,copy],n)=>`<article class="sequence-step" data-step="${n}"><span class="sequence-number">0${n+1}</span><div class="sequence-icon">${icon(i,25)}</div><h3>${title}</h3><p>${copy}</p><span class="sequence-status">${['Context shared','Work assigned','Direction agreed','Knowledge saved'][n]}</span></article>`).join('')}</div><p class="sequence-footnote">An illustration of the connected workflow. Try it yourself in the demo.</p></div>`;}
